p=argparse.ArgumentParser(description=__doc__);p.add_argument('input',type=Path);p.add_argument('--output',type=Path);a=p.parse_args();z=np.load(a.input);f=z['floor_forces'];m=z['motion'];assert f.shape[1]==6 and m.shape[1]==11 and np.isfinite(f).all()and np.isfinite(m).all();assert np.allclose(np.diff(f[:,0]),.001,rtol=0,atol=1e-8);tail=m[m[:,0]>=10];r=dict(input_sha256=hashlib.sha256(a.input.read_bytes()).hexdigest(),duration_s=float(m[-1,0]),peak_nonfoot_normal_n=float(f[:,5].max()),maximum150ms_nonfoot_impulse_ns=float(np.convolve(f[:,5],np.ones(150),mode='valid').max()*.001),stable_ground_final2s=bool((f[f[:,0]>=10,5]>.1).all()and(np.linalg.norm(tail[:,5:8],axis=1)<.1).all()and(np.linalg.norm(tail[:,8:11],axis=1)<.35).all()),stable_standing_final2s=bool(((tail[:,3]>.65)&(tail[:,4]>.9)&(np.linalg.norm(tail[:,5:7],axis=1)<.15)&(np.linalg.norm(tail[:,8:11],axis=1)<.35)).all()),regional_peak_n=dict(zip(['head','hand','torso','other_nonfoot'],[float(v.max())for v in[f[:,1],f[:,2],f[:,3],np.maximum(0,f[:,5]-f[:,1:4].sum(1))]])));s=json.dumps(r,indent=2)+'\n';a.output.write_text(s)if a.output else print(s,end='')
